// Bundled native static libraries in rlibs against oracle-built rlibs (lane link-rlib-native). The crate is `#![no_core]`
// (the three sizedness lang items, `extern "C" { fn foo(x: i32) -> i32; }`, `pub fn f() {}`), built by the oracle with
// `--crate-type rlib --emit=link -Zcodegen-backend=dummy -L <dir>` and the `-l` flags each fixture names. The input static
// libraries were built from C with the host's clang, `ar`, `lipo` and the toolchain's `llvm-ar`, not by the port.
// `ArArchiveBuilder` must rebuild each rlib byte for byte from the oracle's own `lib.rmeta` and `lib.rmeta-link` members
// and the input archives; whole compilations are compared in docs/handoff/link-rlib-native.md.
import { afterAll, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { Session } from "../../rustc_session/session.ts";
import { FileSearch } from "../../rustc_session/filesearch.ts";
import { type PathKind, SearchPath } from "../../rustc_session/search_paths.ts";
import { OSVersion } from "../../rustc_target/spec/base/apple/mod.ts";
import type { Target } from "../../rustc_target/spec/mod.ts";
import { DEFAULT_OBJECT_READER } from "../../vendor/ar_archive_writer/lib.ts";
import { ArchiveFile } from "../../vendor/object/read/archive.ts";
import { File } from "../../vendor/object/read/any.ts";
import { ArArchiveBuilder } from "./archive.ts";
import { try_find_native_static_library } from "./link.ts";
import { create_wrapper_file } from "./metadata.ts";
import { RmetaLink } from "./rmeta_link.ts";

const b64 = (s: string): Uint8Array => Uint8Array.from(Buffer.from(s, "base64"));

/** Input, host `ar rcs`: `libfoo.a` with arm64 `foo.o`, `bar.o` (BSD archive, `__.SYMDEF SORTED`). */
const LIBFOO_MACHO = b64("");

/** Input, host `ar rcs`: `libbaz.a`, other arm64 objects under the same member names `foo.o`, `bar.o`. */
const LIBBAZ_MACHO = b64("");

/** Input, `lipo -create`: a universal file holding the x86_64 and the arm64 `libfoo.a` (arm64 the same bytes as `LIBFOO_MACHO`). */
const LIBFAT_MACHO = b64("");

/** Input, `llvm-ar rcs --format=gnu`: `libfoo.a` with x86_64 ELF `foo.o`, `bar.o`. */
const LIBFOO_ELF = b64("");

/** Input, `llvm-ar rcs --format=gnu`: `libbaz.a`, other x86_64 ELF objects under the same member names. */
const LIBBAZ_ELF = b64("");

/** Oracle: `-l static=foo -l static=baz`, host. */
const RLIB_HOST_FOO_BAZ = b64("");

/** Oracle: `-l static:+whole-archive=foo`, host: `libfoo.a` packed as a `.bundled_lib` wrapper. */
const RLIB_HOST_WHOLE_ARCHIVE = b64("");

/** Oracle: `-l static=foo -l static=baz`, `--target x86_64-unknown-linux-gnu`. */
const RLIB_ELF_FOO_BAZ = b64("");

const DIR = mkdtempSync(join(tmpdir(), "rlib-native-"));
afterAll(() => rmSync(DIR, { recursive: true, force: true }));
let seq = 0;

function fresh_dir(files: Record<string, Uint8Array>): string {
  const d = mkdtempSync(join(DIR, `${seq++}-`));
  for (const [n, data] of Object.entries(files)) writeFileSync(join(d, n), data);
  return d;
}

/** What the archive builder and `create_wrapper_file` ask of the session. */
function sess(llvm_target: string, arch: string, archive_format: string, macho: boolean): Session {
  const target = {
    llvm_target,
    os: { $: macho ? "MacOs" : "Linux" },
    env: { $: macho ? "Unspecified" : "Gnu" },
    arch: { $: arch },
    // `os` and `env` at both levels: `create_object_file` reads them from `options` (`elf_os_abi`), others from the target.
    options: { archive_format, endian: "Little", binary_format: macho ? "MachO" : "Elf", is_like_darwin: macho, is_like_wasm: false, os: { $: macho ? "MacOs" : "Linux" }, env: { $: macho ? "Unspecified" : "Gnu" } },
    object_architecture: () => [arch === "AArch64" ? "Aarch64" : "X86_64", undefined],
  } as unknown as Target;
  return {
    target,
    internal_target_features: new Set(),
    apple_deployment_target: () => OSVersion.minimum_deployment_target(target),
    dcx: () => {
      throw new Error("unexpected diagnostic");
    },
  } as unknown as Session;
}

const HOST = sess("arm64-apple-macosx", "AArch64", "darwin", true);
const ELF = sess("x86_64-unknown-linux-gnu", "X86_64", "gnu", false);

const utf8 = (b: Uint8Array): string => new TextDecoder().decode(b);

function members(rlib: Uint8Array): [string, Uint8Array][] {
  const a = ArchiveFile.parse(rlib);
  if (a.$ !== "Ok") throw new Error("fixture archive");
  return [...a._0.members()].map((m) => {
    if (m.$ !== "Ok") throw new Error("fixture member");
    const d = m._0.data(rlib);
    if (d.$ !== "Ok") throw new Error("fixture data");
    return [utf8(m._0.name()), d._0];
  });
}

function section(obj: Uint8Array, name: string): Uint8Array {
  const f = File.parse(obj);
  if (f.$ !== "Ok") throw new Error("not an object file");
  const s = f._0.section_by_name_bytes(new TextEncoder().encode(name));
  if (s === undefined) throw new Error(`no section ${name}`);
  const d = s.data();
  if (d.$ !== "Ok") throw new Error("section data");
  return d._0;
}

/** `link_rlib`'s calls for an rlib whose metadata comes first: `lib.rmeta`, `lib.rmeta-link`, then each archive. */
function rebuild(s: Session, rlib: Uint8Array, archives: string[]): Uint8Array {
  const [[, rmeta], [, link]] = members(rlib) as [[string, Uint8Array], [string, Uint8Array]];
  const d = fresh_dir({ "lib.rmeta": rmeta, "lib.rmeta-link": link });
  const ab = ArArchiveBuilder.new(s, DEFAULT_OBJECT_READER);
  ab.add_file(join(d, "lib.rmeta"), "Other");
  ab.add_file(join(d, "lib.rmeta-link"), "Other");
  for (const a of archives) expect(ab.add_archive(a, { $: "Other" })).toEqual({ $: "Ok", _0: null });
  const out = join(d, "libnc.rlib");
  expect(ab.build(out)).toBe(true);
  return readFileSync(out);
}

const INPUTS = fresh_dir({
  "libfoo.a": LIBFOO_MACHO,
  "libbaz.a": LIBBAZ_MACHO,
  "libfat.a": LIBFAT_MACHO,
});
const ELF_INPUTS = fresh_dir({ "libfoo.a": LIBFOO_ELF, "libbaz.a": LIBBAZ_ELF });

test("the fixtures hold the members the oracle bundled", () => {
  expect(members(RLIB_HOST_FOO_BAZ).map(([n]) => n)).toEqual(["lib.rmeta", "lib.rmeta-link", "foo.o", "bar.o", "foo.o", "bar.o"]);
  expect(members(RLIB_ELF_FOO_BAZ).map(([n]) => n)).toEqual(["lib.rmeta", "lib.rmeta-link", "foo.o", "bar.o", "foo.o", "bar.o"]);
  expect(members(RLIB_HOST_WHOLE_ARCHIVE).map(([n]) => n)).toEqual(["lib.rmeta", "lib.rmeta-link", "libfoo.a"]);
});

test("the foo/baz rlibs' rmeta-link records list two unpacked native libraries, and the host's is the port's byte for byte (review N2)", () => {
  // `native_lib_filenames` has one entry per bundled library: `None` where it is unpacked into the rlib (not `+whole-archive`).
  for (const rlib of [RLIB_HOST_FOO_BAZ, RLIB_ELF_FOO_BAZ]) {
    const [, [, link]] = members(rlib) as [[string, Uint8Array], [string, Uint8Array]];
    const record = RmetaLink.decode(section(link, ".rmeta-link"));
    expect([record?.rust_object_files, record?.native_lib_filenames]).toEqual([[], [undefined, undefined]]);
  }
  // A darwin archive pads a member to 8 bytes, a GNU one to 2, with `\n` (root-w43-check N2: the ELF wrapper too).
  for (const [sess, rlib, align] of [[HOST, RLIB_HOST_FOO_BAZ, 8], [ELF, RLIB_ELF_FOO_BAZ, 2]] as const) {
    const [, [, link]] = members(rlib) as [[string, Uint8Array], [string, Uint8Array]];
    const written = [...create_wrapper_file(sess, ".rmeta-link", new RmetaLink([], [undefined, undefined]).encode())[0]];
    while (written.length % align !== 0) written.push(0x0a);
    expect(written).toEqual([...link]);
  }
});

test("add_archive of two Mach-O archives with the same member names rebuilds the host rlib", () => {
  const got = rebuild(HOST, RLIB_HOST_FOO_BAZ, [join(INPUTS, "libfoo.a"), join(INPUTS, "libbaz.a")]);
  expect([...got]).toEqual([...RLIB_HOST_FOO_BAZ]);
});

test("add_archive skips an archive already added (`-l static=foo` twice)", () => {
  const foo = join(INPUTS, "libfoo.a");
  const got = rebuild(HOST, RLIB_HOST_FOO_BAZ, [foo, foo, join(INPUTS, "libbaz.a"), foo]);
  expect([...got]).toEqual([...RLIB_HOST_FOO_BAZ]);
});

test("add_archive takes the arm64 slice of a universal file on the host", () => {
  const saved = process.env.TMPDIR;
  // `try_extract_macho_fat_archive` keeps its temp file, as upstream does: put it where the test cleans up.
  process.env.TMPDIR = fresh_dir({});
  try {
    const got = rebuild(HOST, RLIB_HOST_FOO_BAZ, [join(INPUTS, "libfat.a"), join(INPUTS, "libbaz.a")]);
    expect([...got]).toEqual([...RLIB_HOST_FOO_BAZ]);
  } finally {
    if (saved === undefined) delete process.env.TMPDIR;
    else process.env.TMPDIR = saved;
  }
});

test("add_archive of two GNU archives of ELF objects rebuilds the x86_64-unknown-linux-gnu rlib", () => {
  const got = rebuild(ELF, RLIB_ELF_FOO_BAZ, [join(ELF_INPUTS, "libfoo.a"), join(ELF_INPUTS, "libbaz.a")]);
  expect([...got]).toEqual([...RLIB_ELF_FOO_BAZ]);
});

test("+whole-archive: the .bundled_lib wrapper, the rmeta-link record of its file name, and the whole rlib", () => {
  const [[, rmeta], [, link], [, packed]] = members(RLIB_HOST_WHOLE_ARCHIVE) as [string, Uint8Array][] as [[string, Uint8Array], [string, Uint8Array], [string, Uint8Array]];
  expect([...section(packed, ".bundled_lib")]).toEqual([...LIBFOO_MACHO]);
  // A darwin archive pads each member to 8 bytes with `\n`, and the padding counts in the member's size.
  const pad = (b: Uint8Array): number[] => {
    const v = [...b];
    while (v.length % 8 !== 0) v.push(0x0a);
    return v;
  };
  expect(pad(create_wrapper_file(HOST, ".bundled_lib", LIBFOO_MACHO)[0])).toEqual([...packed]);
  expect(pad(create_wrapper_file(HOST, ".rmeta-link", new RmetaLink([], ["libfoo.a"]).encode())[0])).toEqual([...link]);

  const d = fresh_dir({ "lib.rmeta": rmeta, "lib.rmeta-link": link, "libfoo.a": create_wrapper_file(HOST, ".bundled_lib", LIBFOO_MACHO)[0] });
  const ab = ArArchiveBuilder.new(HOST, DEFAULT_OBJECT_READER);
  for (const n of ["lib.rmeta", "lib.rmeta-link", "libfoo.a"]) ab.add_file(join(d, n), "Other");
  expect(ab.build(join(d, "libnc.rlib"))).toBe(true);
  expect([...readFileSync(join(d, "libnc.rlib"))]).toEqual([...RLIB_HOST_WHOLE_ARCHIVE]);
});

/** The search `find_native_static_library` does, for `-L` flags as the oracle saw them (results in the handoff). */
function search_sess(paths: [PathKind, string][]): Session {
  const cli = paths.map(([k, d]) => new SearchPath(k, d));
  const fs = new FileSearch(cli, new SearchPath("All", join(DIR, "no-sysroot")), false, []);
  return {
    target: { staticlib_prefix: "lib", staticlib_suffix: ".a" },
    target_filesearch: () => fs,
    staticlib_components(verbatim: boolean): [string, string] {
      return verbatim ? ["", ""] : ["lib", ".a"];
    },
  } as unknown as Session;
}

test("try_find_native_static_library follows the oracle's -L kinds and +verbatim", () => {
  const foo = join(INPUTS, "libfoo.a");
  expect(try_find_native_static_library(search_sess([["All", INPUTS]]), "foo", false)).toBe(foo);
  expect(try_find_native_static_library(search_sess([["Native", INPUTS]]), "foo", false)).toBe(foo);
  // `-L framework=.` and `-L dependency=.`: "could not find native static library `foo`" from the oracle.
  expect(try_find_native_static_library(search_sess([["Framework", INPUTS]]), "foo", false)).toBeUndefined();
  expect(try_find_native_static_library(search_sess([["Dependency", INPUTS]]), "foo", false)).toBeUndefined();
  // The first directory that has it wins; a missing directory is skipped.
  expect(try_find_native_static_library(search_sess([["All", join(DIR, "nonexistent")], ["All", ELF_INPUTS], ["All", INPUTS]]), "foo", false)).toBe(
    join(ELF_INPUTS, "libfoo.a"),
  );
  // `+verbatim=libfoo.a` is found; `+verbatim=foo` and a plain `libfoo.a` are not.
  expect(try_find_native_static_library(search_sess([["All", INPUTS]]), "libfoo.a", true)).toBe(foo);
  expect(try_find_native_static_library(search_sess([["All", INPUTS]]), "foo", true)).toBeUndefined();
  expect(try_find_native_static_library(search_sess([["All", INPUTS]]), "libfoo.a", false)).toBeUndefined();
});
